'use strict';
const historyBar=document.createElement('div');historyBar.className='history-actions';historyBar.innerHTML='<button class="btn btn-ghost btn-sm" id="undoEdit" title="Undo (Ctrl+Z)" aria-label="Undo">↶ Undo</button><button class="btn btn-ghost btn-sm" id="redoEdit" title="Redo (Ctrl+Shift+Z)" aria-label="Redo">↷ Redo</button>';
document.querySelector('.project-actions').prepend(historyBar);
let editHistory=[],redoHistory=[],editHistoryTimer=null,restoringHistory=false;const imageIdentity=new WeakMap();let nextImageIdentity=1;
function snapshotEdit(){captureDesignSide();const pack=s=>{const out={id:s.id,kind:s.kind,fontChoice:s.fontChoice,sourceLabel:s.sourceLabel,imageName:s.imageName,image:s.image};for(const k of SIDE_KEYS)out[k]=s[k];return out;};return {settings:collectSettings(),layers:designLayers.map(list=>list.map(pack)),side:activeDesignSide,selected:designSides.map(s=>s?.id||null),linked:linkedSideSettings,bottom:{...bottomBrand},name:$('projectName').value};}
function editKey(s){return JSON.stringify({...s,side:undefined,selected:undefined,settings:{...s.settings,...Object.fromEntries(SIDE_KEYS.map(k=>[k,undefined]))}},(key,value)=>{if(key==='image'&&value){if(!imageIdentity.has(value))imageIdentity.set(value,nextImageIdentity++);return imageIdentity.get(value);}return value;});}
function syncHistoryButtons(){$('undoEdit').disabled=editHistory.length<2||exportBusy;$('redoEdit').disabled=!redoHistory.length||exportBusy;}
function commitEditHistory(){clearTimeout(editHistoryTimer);editHistoryTimer=null;if(restoringHistory)return;const snap=snapshotEdit(),key=editKey(snap);if(editHistory.at(-1)?.key!==key){editHistory.push({key,snap});if(editHistory.length>40)editHistory.shift();redoHistory=[];}syncHistoryButtons();}
function resetEditHistory(){clearTimeout(editHistoryTimer);editHistory=[];redoHistory=[];commitEditHistory();}
function restoreEdit(s){restoringHistory=true;clearTimeout(AppState.rebuildTimer);AppState.rebuildTimer=null;hidePlacementPreview();setTemplateMove(false);loadSettings(s.settings);designLayers=s.layers.map((list,i)=>list.map(data=>({...emptyDesignSide(i),...data,cache:null})));activeDesignSide=s.side;designSides=designLayers.map((list,i)=>list.find(v=>v.id===s.selected[i])||list[0]||emptyDesignSide(i));linkedSideSettings=s.linked;restoreBottomBrand(s.bottom);$('projectName').value=s.name;loadSelectedSlot(designSides[s.side]);if(templateActive())requestTemplatePreview();else if(AppState.image)scheduleRebuild(true);historyOriginalDirty();restoringHistory=false;syncHistoryButtons();}
function undoEdit(){if(exportBusy)return;commitEditHistory();if(editHistory.length<2)return;redoHistory.push(editHistory.pop());restoreEdit(editHistory.at(-1).snap);toast('Undone','success');}
function redoEdit(){if(exportBusy)return;clearTimeout(editHistoryTimer);if(!redoHistory.length)return;const entry=redoHistory.pop();editHistory.push(entry);restoreEdit(entry.snap);toast('Redone','success');}
$('undoEdit').onclick=undoEdit;$('redoEdit').onclick=redoEdit;
const historyOriginalDirty=dirty;dirty=function(){historyOriginalDirty();if(!restoringHistory){clearTimeout(editHistoryTimer);editHistoryTimer=setTimeout(commitEditHistory,550);}};
document.addEventListener('keydown',e=>{if(!(e.ctrlKey||e.metaKey)||e.altKey)return;const key=e.key.toLowerCase();if(key!=='z'&&key!=='y')return;const t=e.target;if(t?.isContentEditable||t?.tagName==='TEXTAREA'||(t?.tagName==='INPUT'&&['text','search'].includes(t.type)))return;e.preventDefault();e.stopImmediatePropagation();if(key==='y'||e.shiftKey)redoEdit();else undoEdit();},true);
const rail=document.createElement('nav');rail.className='tool-rail';rail.setAttribute('aria-label','Studio tools');
const shortcuts=[['☰','Show tools',()=>openTool('designSidesPanel')],['▧','Add image',()=>{openTool('uploadBtn');els.fileInput.click();}],['T＋','Add text',()=>$('addTextLayer').click()],['▤','Design layers',()=>openTool('designSidesPanel')],['↔','Size',()=>openTool('placementFields')],['◐','Depth and finish',()=>openTool('depthIn')],['◩','Image processing',()=>openTool('bgEnable')],['↶','Undo (Ctrl+Z)',undoEdit],['↷','Redo (Ctrl+Shift+Z)',redoEdit]];
for(const [icon,label,action]of shortcuts){const b=document.createElement('button');b.className='rail-button';b.type='button';b.textContent=icon;b.title=label;b.setAttribute('aria-label',label);b.onclick=action;rail.appendChild(b);}document.querySelector('.sidebar').prepend(rail);
function openTool(id){setSettingsOpen(true);requestAnimationFrame(()=>$(id)?.scrollIntoView({block:'nearest',behavior:'smooth'}));}
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',resetEditHistory);else resetEditHistory();
